#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Point {
    ll x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int m = 4 * n + 1;
    vector<Point> points(m);

    ll minX = LLONG_MAX, maxX = LLONG_MIN;
    ll minY = LLONG_MAX, maxY = LLONG_MIN;

    for (auto &[x, y] : points) {
        cin >> x >> y;
        minX = min(minX, x);
        maxX = max(maxX, x);
        minY = min(minY, y);
        maxY = max(maxY, y);
    }

    vector<int> exclusions{-1};

    auto addUniqueExtreme = [&](auto predicate) {
        int index = -1;
        int count = 0;
        for (int i = 0; i < m; ++i) {
            if (predicate(points[i])) {
                index = i;
                ++count;
            }
        }
        if (count == 1)
            exclusions.push_back(index);
    };

    addUniqueExtreme([&](const Point &p) { return p.x == minX; });
    addUniqueExtreme([&](const Point &p) { return p.x == maxX; });
    addUniqueExtreme([&](const Point &p) { return p.y == minY; });
    addUniqueExtreme([&](const Point &p) { return p.y == maxY; });

    sort(exclusions.begin(), exclusions.end());
    exclusions.erase(unique(exclusions.begin(), exclusions.end()),
                     exclusions.end());

    set<array<ll, 4>> checked;

    for (int excluded : exclusions) {
        ll left = LLONG_MAX, right = LLONG_MIN;
        ll bottom = LLONG_MAX, top = LLONG_MIN;

        for (int i = 0; i < m; ++i) {
            if (i == excluded)
                continue;
            left = min(left, points[i].x);
            right = max(right, points[i].x);
            bottom = min(bottom, points[i].y);
            top = max(top, points[i].y);
        }

        if (left == LLONG_MAX || right - left != top - bottom)
            continue;

        array<ll, 4> square{left, right, bottom, top};
        if (!checked.insert(square).second)
            continue;

        int outsideCount = 0;
        Point answer{};

        for (const Point &p : points) {
            bool onBoundary =
                ((p.x == left || p.x == right) &&
                 p.y >= bottom && p.y <= top) ||
                ((p.y == bottom || p.y == top) &&
                 p.x >= left && p.x <= right);

            if (!onBoundary) {
                answer = p;
                if (++outsideCount > 1)
                    break;
            }
        }

        if (outsideCount == 1) {
            cout << answer.x << ' ' << answer.y;
            return 0;
        }
    }

    return 0;
}

