        for (ll right : rights) {
            if (right < left) continue;

            for (ll bottom : bottoms) {
                for (ll top : tops) {
                    if (top < bottom || right - left != top - bottom) continue;

                    int outsideCount = 0;
                    pair<ll, ll> answer;

                    for (auto [x, y] : points) {
                        bool onBoundary =
                            ((x == left || x == right) &&
                             bottom <= y && y <= top) ||
                            ((y == bottom || y == top) &&
                             left <= x && x <= right);

                        if (!onBoundary) {
                            answer = {x, y};
                            if (++outsideCount > 1) break;
                        }
                    }

                    if (outsideCount == 1) {
                        cout << answer.first << ' ' << answer.second;
                        return 0;
                    }
                }
            }
        }
    }

    return 0;
}

